CREATE DATABASE IF NOT EXISTS royal_market_place CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE royal_market_place;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin','owner') NOT NULL DEFAULT 'customer',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,icon VARCHAR(20) DEFAULT '▦',description VARCHAR(500),sort_order INT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,category_id BIGINT UNSIGNED NULL,description TEXT,price DECIMAL(12,2) NOT NULL DEFAULT 0,compare_price DECIMAL(12,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,image_url VARCHAR(1000),is_featured TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(is_active,created_at)) ENGINE=InnoDB;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,customer_name VARCHAR(120) NOT NULL,email VARCHAR(190),phone VARCHAR(30) NOT NULL,address VARCHAR(1000) NOT NULL,city VARCHAR(100) NOT NULL,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(30) NOT NULL DEFAULT 'COD',status ENUM('pending','confirmed','processing','ready_for_dispatch','shipped','delivered','cancelled','returned','refunded') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,product_name VARCHAR(180) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,line_total DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT) ENGINE=InnoDB;
